module Repeater(
  input         clock,
  input         reset,
  input         io_repeat,
  output        io_full,
  output        io_enq_ready,
  input         io_enq_valid,
  input  [2:0]  io_enq_bits_opcode,
  input  [2:0]  io_enq_bits_size,
  input         io_enq_bits_source,
  input  [11:0] io_enq_bits_address,
  input         io_deq_ready,
  output        io_deq_valid,
  output [2:0]  io_deq_bits_opcode,
  output [2:0]  io_deq_bits_size,
  output        io_deq_bits_source,
  output [11:0] io_deq_bits_address
);
  reg  full;
  reg [2:0] saved_opcode;
  reg [2:0] saved_size;
  reg  saved_source;
  reg [11:0] saved_address;
  assign io_full = full;
  assign io_enq_ready = io_deq_ready & ~full;
  assign io_deq_valid = io_enq_valid | full;
  assign io_deq_bits_opcode = full ? saved_opcode : io_enq_bits_opcode;
  assign io_deq_bits_size = full ? saved_size : io_enq_bits_size;
  assign io_deq_bits_source = full ? saved_source : io_enq_bits_source;
  assign io_deq_bits_address = full ? saved_address : io_enq_bits_address;
  always @(posedge clock) begin
    if (reset) begin
      full <= 1'h0;
    end else if (io_deq_ready & io_deq_valid & ~io_repeat) begin
      full <= 1'h0;
    end else begin
      full <= io_enq_ready & io_enq_valid & io_repeat | full;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_opcode <= io_enq_bits_opcode;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_size <= io_enq_bits_size;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_source <= io_enq_bits_source;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_address <= io_enq_bits_address;
    end
  end
endmodule
