    end else if (~ctrl_killd) begin
      id_reg_fence <= id_fence_next | _GEN_0;
    end else if (~id_mem_busy) begin
      id_reg_fence <= 1'h0;
    end
    if (~ctrl_killd) begin
      if (id_illegal_insn) begin
        ex_reg_rs_bypass_0 <= 1'h0;
      end else begin
        ex_reg_rs_bypass_0 <= do_bypass;
      end
    end
    if (~ctrl_killd) begin
      ex_reg_rs_bypass_1 <= do_bypass_1;
    end
    if (~ctrl_killd) begin
      if (id_illegal_insn) begin
        ex_reg_rs_lsb_0 <= inst[1:0];
      end else if (id_ctrl_decoder_7 & ~do_bypass) begin
        ex_reg_rs_lsb_0 <= id_rs_0[1:0];
      end else if (id_bypass_src_0_0) begin
        ex_reg_rs_lsb_0 <= 2'h0;
      end else begin
        ex_reg_rs_lsb_0 <= _bypass_src_T_1;
      end
    end
    if (~ctrl_killd) begin
      if (id_ctrl_decoder_6 & ~do_bypass_1) begin
        ex_reg_rs_lsb_1 <= id_rs_1[1:0];
      end else if (id_bypass_src_1_0) begin
        ex_reg_rs_lsb_1 <= 2'h0;
      end else if (id_bypass_src_1_1) begin
        ex_reg_rs_lsb_1 <= 2'h1;
      end else begin
        ex_reg_rs_lsb_1 <= _bypass_src_T_2;
      end
    end
    if (~ctrl_killd) begin
      if (id_illegal_insn) begin
        ex_reg_rs_msb_0 <= {{32'd0}, inst[31:2]};
      end else if (id_ctrl_decoder_7 & ~do_bypass) begin
        ex_reg_rs_msb_0 <= id_rs_0[63:2];
      end
    end
    if (~ctrl_killd) begin
      if (id_ctrl_decoder_6 & ~do_bypass_1) begin
        ex_reg_rs_msb_1 <= id_rs_1[63:2];
      end
    end
    if (reset) begin
      _r <= 32'h0;
    end else if (ll_wen | wb_set_sboard & wb_wen) begin
      _r <= _T_148;
    end else if (ll_wen) begin
      _r <= _T_143;
    end
    blocked <= ~io_dmem_req_ready & ~io_dmem_perf_grant & (blocked | io_dmem_req_valid | io_dmem_s2_nack);
